cwnd, ssthresh = 1, 16
for step in range(20):
    if cwnd < ssthresh:
        cwnd *= 2          # 慢开始：指数增长
    else:
        cwnd += 1          # 拥塞避免：线性增长
    if cwnd > 40:          # 模拟一次丢包
        ssthresh = max(cwnd // 2, 2)
        cwnd = ssthresh
    print(step, cwnd, ssthresh)
